import React, {useState} from 'react';
import Form from 'arui-feather/form';
import FormField from 'arui-feather/form-field';
import Button from 'arui-feather/button';
import InputGroup from 'arui-feather/input-group';
import Input from 'arui-feather/input';
import {randomInt} from '../utils';
import Spin from 'arui-feather/spin';
import Heading from 'arui-feather/heading';
import Notification from 'arui-feather/notification';
import IconError from 'arui-feather/icon/ui/error';
import IconOk from 'arui-feather/icon/ui/ok';

function CardForm({url, title}) {
  const [loading, setLoading] = useState(false);
  const [success, setSuccess] = useState(false);
  const [error, setError] = useState(false);
  const [number, setNumber] = useState('');
  const [numberError, setNumberError] = useState(null);
  const [month, setMonth] = useState('');
  const [monthError, setMonthError] = useState(null);
  const [year, setYear] = useState('');
  const [yearError, setYearError] = useState(null);
  const [holder, setHolder] = useState('');
  const [holderError, setHolderError] = useState(null);
  const [cvc, setCvc] = useState('');
  const [cvcError, setCvcError] = useState(null);

  const handleSubmit = e => {
    e.preventDefault();
    let hasError = false;

    if (number.trim() === '') {
      hasError = true;
      setNumberError('Поле обязательно для заполнения');
    }

    if (month.trim() === '') {
      hasError = true;
      setMonthError('Поле обязательно для заполнения');
    }

    if (year.trim() === '') {
      hasError = true;
      setYearError('Поле обязательно для заполнения');
    }

    if (holder.trim() === '') {
      hasError = true;
      setHolderError('Поле обязательно для заполнения');
    }

    if (cvc.trim() === '') {
      hasError = true;
      setHolderError('Поле обязательно для заполнения');
    }

    if (!/\d{4} \d{4} \d{4} \d{4}/.test(number)) {
      hasError = true;
      setNumberError('Неверный формат');
    }

    if (!/\d{2}/.test(month)) {
      hasError = true;
      setMonthError('Неверный формат');
    }

    if (!/\d{2}/.test(year)) {
      hasError = true;
      setYearError('Неверный формат');
    }

    if (!/[- A-Z]*/.test(holder)) {
      hasError = true;
      setHolderError('Неверный формат');
    }

    if (!/\d{3}/.test(cvc)) {
      hasError = true;
      setCvcError('Неверный формат');
    }

    if (hasError) {
      return;
    }

    const currentDate = new Date();
    const monthValue = Number.parseInt(month, 10);
    const yearValue = Number.parseInt(year, 10);
    const currentMonthValue = currentDate.getMonth() + 1;
    const currentYearValue = currentDate.getFullYear() % 100;
    const maxYearValue = currentYearValue + 5;

    if (yearValue < currentYearValue) {
      hasError = true;
      setYearError('Истёк срок действия карты');
    } else if (yearValue > maxYearValue) {
      hasError = true;
      setYearError('Неверно указан срок действия карты');
    } else {
      setYearError(null);
    }

    if (monthValue > 12) {
      hasError = true;
      setMonthError('Неверно указан срок действия карты');
    } else if (yearValue === currentYearValue && monthValue < currentMonthValue) {
      hasError = true;
      setMonthError('Неверно указан срок действия карты');
    } else {
      setMonthError(null);
    }

    if (hasError) {
      return;
    }

    setLoading(true);
    setTimeout(async () => {
      setLoading(false);

      try {
        const response = await fetch(url, {
          method: 'POST',
          headers: {'Content-Type': 'application/json'},
          body: JSON.stringify({number, year, month, holder, cvc})
        });

        if (!response.ok) {
          throw Error('Something bad happened');
        }

        setError(false);
        setSuccess(true);
      } catch (e) {
        setSuccess(false);
        setError(true);
      }

      setSuccess(true);
    }, randomInt(1000, 10000));
  };

  return (
    <React.Fragment>
      <Heading size='m'>{title}</Heading>
      <Form onSubmit={handleSubmit}>
        <fieldset disabled={loading}>
          <FormField>
            <Input
              type='text'
              label='Номер карты'
              width='available'
              mask='1111 1111 1111 1111'
              placeholder='0000 0000 0000 0000'
              value={number}
              onChange={setNumber}
              error={numberError}
            />
          </FormField>
          <FormField>
            <InputGroup
              width='available'
            >
              <Input
                label='Месяц'
                mask='11'
                placeholder='08'
                value={month}
                onChange={setMonth}
                error={monthError}
              />
              <Input
                label='Год'
                mask='11'
                placeholder='22'
                value={year}
                onChange={setYear}
                error={yearError}
              />
            </InputGroup>
          </FormField>
          <FormField>
            <InputGroup width='available'>
              <Input
                type='text'
                label='Владелец'
                width='available'
                value={holder}
                onChange={setHolder}
                error={holderError}
              />
              <Input
                label='CVC/CVV'
                mask='111'
                placeholder='999'
                value={cvc}
                onChange={setCvc}
                error={cvcError}
              />
            </InputGroup>
          </FormField>
          <FormField>
            <Button view='extra' onClick={handleSubmit} disabled={loading}>
              <Spin visible={loading}/>&nbsp;
              {!loading && 'Продолжить'}
              {loading && 'Отправляем запрос в Банк...'}
            </Button>
          </FormField>
        </fieldset>
      </Form>
      <Notification
        title='Успешно'
        status='ok'
        visible={success}
        icon={<IconOk theme='alfa-on-color' size='m'/>}
        onCloseTimeout={() => setSuccess(false)}
        onCloserClick={() => setSuccess(false)}
      >
        Операция одобрена Банком.
      </Notification>
      <Notification
        title='Ошибка'
        status='error'
        visible={error}
        icon={<IconError theme='alfa-on-color' size='m'/>}
        onCloseTimeout={() => setError(false)}
        onCloserClick={() => setError(false)}
      >
        Ошибка! Банк отказал в проведении операции.
      </Notification>
    </React.Fragment>
  );
}

export default CardForm;
