import React, {useState} from 'react';
import Heading from 'arui-feather/heading';
import styles from './Order.module.css';
import GridRow from 'arui-feather/grid-row';
import GridCol from 'arui-feather/grid-col';
import card from './marrakech.jpg';
import List from 'arui-feather/list';
import Button from 'arui-feather/button';
import CardForm from './CardForm';

function Order({onSuccess}) {
  const properties = [
    {key: '1', value: 'Сказочный Восток'},
    {key: '2', value: '33 360 миль на карту'},
    {key: '3', value: 'До 7% на остаток по счёту'},
    {key: '4', value: 'Всего 45 000 руб.!'},
  ];

  const [type, setType] = useState('');

  const handlePay = (e) => {
    e.preventDefault();
    setType('pay');
  };
  const handleCredit = (e) => {
    e.preventDefault();
    setType('credit');
  };

  return (
    <React.Fragment>
      <Heading size='l'>Путешествие дня</Heading>
      <div className={styles.cardPreview}>
        <GridRow>
          <GridCol>
            <img
              className={styles.cardImage}
              src={card}
              alt='Марракэш'/>
          </GridCol>
          <GridCol>
            <Heading className={styles.cardHeading} size='m'>Марракэш</Heading>
            <List items={properties}/>
          </GridCol>
        </GridRow>
      </div>
      <Button onClick={handlePay}>Купить</Button>
      <Button view='extra' onClick={handleCredit}>Купить в кредит</Button>
      {type === 'pay' && <CardForm url={`${process.env.REACT_APP_URL}/pay`} title='Оплата по карте' />}
      {type === 'credit' && <CardForm url={`${process.env.REACT_APP_URL}/credit`} title='Кредит по данным карты' />}
    </React.Fragment>
  );
}

export default Order;
